// Which 3D model (public/models/*.glb) each product uses. Generated by scripts/build-3d-models.mjs
// (BU100E by scripts/build-bu100e-model.mjs). Products not listed keep the holographic photo card.
const M = {
  bu100e: 'bu100e',
  bu100ew: 'bu100e',
  bu30e: 'bu30e',
  bu200e: 'su-short',
  bu200ew: 'su-short',
  'su102-h114': 'su-short',
  bu300e: 'su-tall',
  bu300ew: 'su-tall',
  'su103-h114': 'su-tall',
  'se30-st': 'se',
  'se100-st': 'se',
  'se100w-st': 'se',
  'su102-st': 'su-st',
  'su102w-st': 'su-st',
  al100: 'al100',
  wg100: 'el-wg-100',
  dwg100: 'el-wg-100',
  we100: 'el-we-100',
  ws10: 'ws-cartridge',
  'ws10-25': 'ws-cartridge',
  'ws20-01': 'ws-cartridge',
  'ws20-25': 'ws-cartridge',
  'serie-l': 'strainer-l',
  'serie-ll': 'strainer-ll',
  'serie-of-75s': 'strainer-of',
  mga: 'mag-plate-short',
  mgb110: 'mag-plate-long',
  mgb160: 'mag-disc',
  mgb210: 'mag-box',
  mgr200: 'mag-rect'
};
// filter elements M/E/X/D: <kind><size>-H<height> → el-<kind>-<size>-<height>
const element = slug => {
  const m = /^([mexd])(\d+)-h(\d+)$/.exec(slug);
  return m ? `el-${m[1]}-${m[2]}-${m[3]}` : null;
};

export const model3d = slug => {
  const key = M[slug] || element(slug);
  return key ? `/models/${key}.glb` : null;
};
